<script lang="ts">import { enhance } from '$app/forms';import { MessageSquareText, ShieldAlert } from '@lucide/svelte';import ActionToast from '$lib/components/ActionToast.svelte';let{data,form}=$props();const date=(v:string|Date)=>new Date(v).toLocaleString('en-PK',{dateStyle:'medium',timeStyle:'short'});</script><svelte:head><title>Manage feedback | ZAC Admin</title></svelte:head><div class="page-title"><div><span class="eyebrow">Student voice</span><h1>Feedback</h1><p>Questions, suggestions, and corrections shared through ZAC.</p></div></div>{#if form?.error}<ActionToast type="error" message={form.error}/>{/if}{#if form?.success}<ActionToast title="Feedback updated" message="The feedback status has been saved."/>{/if}{#if !data.databaseConfigured||data.databaseError}<div class="admin-alert"><ShieldAlert size={17}/><span><b>{data.databaseConfigured?'Could not load feedback':'Database not configured'}</b><small>Check DATABASE_URL and the database connection.</small></span></div>{:else if data.rows.length}<div class="feedback-list">{#each data.rows as note}<article><div class="feedback-top"><span><MessageSquareText size={14}/>{note.category}</span><time>{date(note.createdAt)}</time><span class="feedback-status {note.status}">{note.status}</span></div><p>{note.message}</p>{#if note.email}<a class="feedback-email" href="mailto:{note.email}">{note.email}</a>{/if}<form method="POST" action="?/status" use:enhance><input type="hidden" name="id" value={note.id}/><label for="status-{note.id}">Update status</label><select id="status-{note.id}" name="status" value={note.status}><option value="new">New</option><option value="reviewed">Reviewed</option><option value="resolved">Resolved</option></select><button class="button button-outline">Save</button></form></article>{/each}</div>{:else}<div class="empty"><MessageSquareText size={22}/><b>No feedback yet</b><span>Anonymous feedback submitted on the public site will appear here.</span></div>{/if}
<style>.feedback-email{display:inline-block;margin:0 0 10px;color:#315f91;font-size:10px;font-weight:600}.page-title{margin-bottom:16px}.page-title h1{font:800 23px Manrope,sans-serif;color:#193c5a;letter-spacing:-.04em;margin:4px 0}.page-title p{font-size:10px;color:#7c8a98;margin:0}.feedback-list{display:grid;gap:9px}.feedback-list article{background:#fff;border:1px solid #e7edf1;border-radius:8px;padding:14px}.feedback-top{display:flex;align-items:center;gap:11px;color:#6b8294}.feedback-top>span:first-child{display:flex;align-items:center;gap:5px;color:#315773;font-size:10px;font-weight:700}.feedback-top time{font-size:9px;color:#8b98a4}.feedback-status{margin-left:auto;font-size:8px;border-radius:10px;padding:4px 8px;background:#f6f1e8;color:#927c4f;text-transform:capitalize}.feedback-status.reviewed{background:#edf3f9;color:#5480a3}.feedback-status.resolved{background:#eaf5ef;color:#548269}.feedback-list p{color:#52687a;font-size:11px;line-height:1.7;white-space:pre-line;margin:12px 0}.feedback-list form{display:flex;align-items:center;gap:7px;border-top:1px solid #f0f2f4;padding-top:10px}.feedback-list label{font-size:9px;color:#82909c}.feedback-list select{font-size:9px;border:1px solid #e2e8ee;border-radius:5px;padding:6px;color:#52687a}.feedback-list button{font-size:9px;padding:7px 10px;margin-left:auto}.empty{min-height:150px;background:white;border:1px solid #e7edf1;border-radius:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:#668a83}.empty b{color:#405e71;font-size:12px}.empty span{color:#83919d;font-size:10px}.admin-alert{display:flex;align-items:center;gap:11px;background:#fff8e9;border:1px solid #f0e2bd;border-radius:8px;padding:13px;color:#96783d}.admin-alert b,.admin-alert small{display:block}.admin-alert b{font-size:11px}.admin-alert small{font-size:9px;margin-top:4px}</style>
